mapper.update:
UPDATE account a
SET

      a.account_type = #{row.accountType},

    a.account_type_verify_status = #{row.accountTypeVerifyStatus},
    a.account_type_verify_source = #{row.accountTypeVerifySource},
    a.account_type_verified_at = #{row.accountTypeVerifiedAt},

      a.business_verification_level = #{row.businessVerificationLevel},
      a.business_verification_source = #{row.businessVerificationSource},
      a.business_verification_verified_at = #{row.businessVerificationVerifiedAt},

    a.updated_at = #{row.updatedAt}
WHERE a.tenant_id = #{row.tenantId}
  AND a.id = #{row.id}
  AND a.protocol_account_id = #{row.protocolAccountId}
  AND UPPER(TRIM(a.protocol_id)) = #{row.protocolId}
  AND a.deleted_at IS NULL
  AND (a.account_type_verified_at IS NULL
       OR a.account_type_verified_at < #{row.accountTypeVerifiedAt})
  AND EXISTS (
    SELECT 1
    FROM account_credential c
    WHERE c.tenant_id = #{row.tenantId}
      AND c.account_id = a.id
      AND c.updated_at = #{credentialVersion}
      AND c.deleted_at IS NULL
  )

